/* MODULE dl05 · Bước 7 Đo lường · Đo thương hiệu: nhận biết, cân nhắc, sức khoẻ
   10 bài × 7 câu. Thương hiệu được nêu như ví dụ công khai; mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'dl05', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:dl05-01', skill:'measure', read:'7 phút', t:'Thương hiệu được biết nhiều mà bán ít: tắc ở tầng nào?',
  situation:'Một hãng nước mắm đóng chai ở Phan Thiết khảo sát 400 người nội trợ tại TP.HCM. Kết quả: 60% biết tên hãng, nhưng chỉ 18% từng mua trong ba tháng qua. Giám đốc muốn tăng gấp đôi ngân sách quảng cáo "cho nhiều người biết hơn nữa". Bạn được giao đọc lại số liệu trước khi duyệt tiền.',
  concept:{ name:'Phễu thương hiệu và tỉ lệ chuyển giữa các tầng',
    body:'Phễu thương hiệu chia hành trình trong đầu khách thành các tầng: <b>biết</b> → <b>cân nhắc</b> (sẵn lòng đưa vào danh sách chọn) → <b>ưa thích</b> (chọn đầu tiên) → <b>mua</b>. Mỗi tầng đọc bằng hai con số: tỉ lệ trên toàn mẫu và <b>tỉ lệ chuyển</b> từ tầng ngay trên. Tầng có tỉ lệ chuyển thấp bất thường so với đối thủ cùng ngành là chỗ tắc. Chỉ nhìn con số cuối (mua) thì không biết nên sửa nhận biết, sửa lý do để cân nhắc hay sửa độ phủ điểm bán.' },
  example:'Tách tiếp khảo sát: biết 60%, cân nhắc 24%, ưa thích 20%, mua 18%. Tỉ lệ chuyển biết → cân nhắc = 24 ÷ 60 = 40%; cân nhắc → ưa thích = 20 ÷ 24 ≈ 83%; ưa thích → mua = 18 ÷ 20 = 90%. Hãng dẫn đầu cùng ngành chuyển biết → cân nhắc khoảng 65%. Chỗ tắc nằm ở tầng cân nhắc: người ta biết tên nhưng không thấy lý do để đưa vào giỏ. Thêm tiền cho nhận biết chỉ đổ thêm người vào đúng chỗ đang rò.',
  takeaway:'Đừng đọc tầng cuối phễu; hãy đọc tỉ lệ chuyển giữa từng tầng và tìm chỗ tụt mạnh nhất so với đối thủ.',
  apply:'Lấy một thương hiệu bạn biết. Ước lượng bốn tầng biết, cân nhắc, ưa thích, mua; tính ba tỉ lệ chuyển và nói trong 60 giây tầng nào đáng sửa trước.',
  mistakes:['Thấy doanh số thấp là tăng ngân sách nhận biết, không kiểm tra các tầng giữa.','So tỉ lệ trên toàn mẫu giữa các tầng thay vì tính tỉ lệ chuyển từ tầng ngay trên.'],
  q:[
  { type:'mcq', stem:'60% biết tên, 18% đã mua. Trước khi có thêm số liệu, bạn đoán vấn đề nằm ở đâu?',
    options:[{k:'a',t:'Nhận biết còn thấp, cần quảng cáo rộng hơn để kéo thêm người biết'},{k:'b',t:'Chưa kết luận được: cần tách tầng giữa biết và mua'},
             {k:'c',t:'Giá quá cao so với các hãng nước mắm công nghiệp'},{k:'d',t:'Mẫu 400 người quá nhỏ nên số 18% không có ý nghĩa gì để đọc'}],
    answer:'b', why:{a:'60% biết là không thấp; khoảng hở lớn nằm sau tầng biết.',
      b:'Đúng. Hai con số đầu và cuối không cho biết khách rơi ở tầng nào.',
      c:'Giá có thể là một lý do, nhưng chưa có dữ kiện nào chỉ về giá.',
      d:'400 người đủ để đọc chênh lệch lớn cỡ 60% và 18%; vấn đề là thiếu tầng giữa.'} },
  { type:'mcq', stem:'Số liệu cho thấy biết → cân nhắc chỉ 40%, đối thủ 65%. Bạn đề xuất gì với giám đốc?',
    options:[{k:'a',t:'Duyệt gấp đôi ngân sách như dự kiến để kéo nhận biết lên 80%'},{k:'b',t:'Giảm giá sâu để người đã cân nhắc chuyển thành mua nhanh hơn'},
             {k:'c',t:'Giữ ngân sách, đổi thông điệp sang lý do để đưa hãng vào danh sách chọn'},{k:'d',t:'Dừng quảng cáo, dồn tiền mở thêm điểm bán ở chợ truyền thống'}],
    answer:'c', why:{a:'Thêm người biết mà tỉ lệ chuyển 40% giữ nguyên thì phần lớn tiền vẫn rò ở tầng cân nhắc.',
      b:'Cân nhắc → mua đã rất cao; giảm giá xử lý sai tầng và bào lãi.',
      c:'Đúng. Chỗ tắc là cân nhắc; cần cho người đã biết một lý do cụ thể để chọn thử.',
      d:'Ưa thích → mua đạt 90%, tức điểm bán không phải điểm nghẽn chính.'} },
  { type:'calc', stem:'Khảo sát 500 người: 300 biết, 120 cân nhắc, 90 ưa thích, 72 đã mua. Tỉ lệ chuyển từ cân nhắc sang ưa thích là bao nhiêu phần trăm?',
    unit:'%', ans:75, tol:0.5, wrong:[[18,'SAI_MAU_SO'],[30,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Tỉ lệ chuyển lấy mẫu số là tầng ngay trên (cân nhắc), không phải toàn mẫu hay tầng biết.','90 ÷ 120 = 0,75 = <b>75%</b>.'] },
  { type:'mcq', stem:'Hãng A: biết 80%, mua 20%. Hãng B: biết 40%, mua 16%. Nhận định nào có căn cứ nhất?',
    options:[{k:'a',t:'A mạnh hơn hẳn B vì có nhiều người mua hơn trên toàn mẫu khảo sát'},{k:'b',t:'B chuyển người biết thành người mua tốt hơn A'},
             {k:'c',t:'B nên học A và dồn tiền vào nhận biết thật nhanh'},{k:'d',t:'Hai hãng ngang nhau vì chênh 4 điểm mua là nhỏ'}],
    answer:'b', why:{a:'A nhiều người mua hơn, nhưng chỉ 25% người biết mua, còn B là 40%.',
      b:'Đúng. B: 16 ÷ 40 = 40%; A: 20 ÷ 80 = 25%. B chuyển hoá tốt, thiếu độ phủ nhận biết.',
      c:'Kết luận có phần đúng hướng, nhưng câu hỏi là đọc hiệu quả chuyển hoá, và B đang chuyển tốt hơn.',
      d:'Chênh tầng cuối nhỏ nhưng chênh tỉ lệ chuyển rất lớn; đó mới là thông tin.'} },
  { type:'mcq', stem:'Một chuỗi cà phê có tỉ lệ ưa thích → mua chỉ 45%, trong khi ngành khoảng 75%. Tắc này thường do đâu?',
    options:[{k:'a',t:'Thông điệp quảng cáo chưa đủ cảm xúc để khiến khách nhớ tới thương hiệu'},{k:'b',t:'Nhận biết quá thấp so với đối thủ'},
             {k:'c',t:'Khách thích nhưng khó mua: ít quán, xa, hết món'},{k:'d',t:'Khảo sát sai vì người thích thì chắc chắn đã mua rồi'}],
    answer:'c', why:{a:'Người đã ưa thích thì không thiếu cảm xúc; họ thiếu điều kiện để mua.',
      b:'Tầng này chỉ đo trong nhóm đã ưa thích, không liên quan độ rộng nhận biết.',
      c:'Đúng. Tắc ở tầng cuối thường là độ sẵn có: điểm bán, giờ mở, hàng có sẵn.',
      d:'Thích mà không mua là chuyện rất thường; khoảng cách đó chính là cái cần đo.'} },
  { type:'mcq', stem:'Vì sao cần so tỉ lệ chuyển với đối thủ cùng ngành thay vì đặt một mốc chung như "cân nhắc phải trên 50%"?',
    options:[{k:'a',t:'Mỗi ngành có nhịp chuyển tự nhiên khác nhau'},{k:'b',t:'Vì đối thủ luôn có số liệu chính xác hơn mình nên lấy làm chuẩn'},
             {k:'c',t:'Vì mốc 50% là chuẩn quốc tế áp dụng được cho mọi ngành hàng tiêu dùng'},{k:'d',t:'Vì so với đối thủ thì con số của mình trông đẹp hơn'}],
    answer:'a', why:{a:'Đúng. Mua xe và mua mì có phễu rất khác; chuẩn phải lấy trong cùng ngành.',
      b:'Số của đối thủ cũng từ khảo sát như mình; lý do so là để có chuẩn cùng ngành.',
      c:'Không có mốc chung cho mọi ngành; mốc cố định dễ dẫn tới kết luận sai.',
      d:'So để tìm chỗ tắc, không phải để làm đẹp báo cáo.'} },
  { type:'mcq', stem:'Câu hỏi nào đo tầng "cân nhắc" đúng nhất?',
    options:[{k:'a',t:'"Bạn đã từng nghe tới thương hiệu X chưa?"'},{k:'b',t:'"Bạn có thích quảng cáo mới nhất của thương hiệu X không, vì sao?"'},
             {k:'c',t:'"Bạn đã mua X lần nào trong ba tháng qua chưa?"'},{k:'d',t:'"Lần tới mua nước mắm, bạn sẵn lòng chọn những hãng nào?"'}],
    answer:'d', why:{a:'Đây là câu đo nhận biết.',
      b:'Thích quảng cáo không đồng nghĩa với sẵn lòng mua; đây là đo phản ứng với quảng cáo.',
      c:'Đây là câu đo hành vi mua.',
      d:'Đúng. Cân nhắc là được đưa vào danh sách chọn cho lần mua tới.'} } ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:dl05-02', skill:'measure', read:'7 phút', t:'Khảo sát 300 người trong nhóm fan: số nhận biết có tin được không?',
  situation:'Một thương hiệu mỹ phẩm thuần chay gửi link khảo sát lên fanpage 120.000 người theo dõi và nhóm Zalo khách hàng. Sau ba ngày có 300 phản hồi, 85% nói "biết thương hiệu", 60% "ưa thích nhất". Nhóm muốn đưa hai con số này vào hồ sơ gọi vốn như sức khoẻ thương hiệu trên thị trường.',
  concept:{ name:'Mẫu đại diện',
    body:'Con số khảo sát chỉ nói về <b>nhóm người được hỏi</b>. Muốn nói về thị trường, mẫu phải giống thị trường mục tiêu ở những đặc điểm quan trọng: khu vực, tuổi, thu nhập, có dùng ngành hàng hay không. Hỏi người theo dõi fanpage là hỏi người đã biết và đã thích — kết quả gần như chắc chắn cao. Cách sửa: định nghĩa rõ tổng thể (ví dụ nữ 20–40 tuổi ở thành phố lớn có dùng mỹ phẩm dưỡng da), lấy mẫu qua kênh không gắn với thương hiệu, đặt <b>chỉ tiêu</b> theo vùng và tuổi, và lọc người không dùng ngành hàng.' },
  example:'Nhóm làm lại qua một panel khảo sát trực tuyến, chỉ tiêu 50% Hà Nội, 50% TP.HCM, chia đều ba nhóm tuổi, lọc người có mua dưỡng da trong sáu tháng. 400 người trả lời: nhận biết có nhắc 22%, ưa thích nhất 4%. Con số thấp hơn nhiều nhưng dùng được để đặt mục tiêu và so với đối thủ; con số 85% chỉ nói fan biết mình, điều hiển nhiên.',
  takeaway:'Trước khi đọc con số khảo sát, hãy hỏi: ai đã được hỏi, và họ có giống người mình muốn bán không?',
  apply:'Viết một câu định nghĩa tổng thể cho khảo sát thương hiệu của bạn (ai, ở đâu, có dùng ngành hàng) và nêu hai chỉ tiêu mẫu bạn sẽ đặt.',
  mistakes:['Gửi khảo sát cho người theo dõi và gọi đó là "thị trường".','Tăng số phản hồi mà không sửa cách chọn người trả lời.'],
  q:[
  { type:'mcq', stem:'85% người trả lời qua fanpage biết thương hiệu. Bạn đoán con số trên thị trường thật sẽ thế nào?',
    options:[{k:'a',t:'Thấp hơn nhiều, vì fan là người đã biết sẵn'},{k:'b',t:'Gần như bằng, vì 300 người đã là một mẫu đủ lớn để suy ra thị trường'},
             {k:'c',t:'Cao hơn, vì fan hay khắt khe khi trả lời'},{k:'d',t:'Không đoán được hướng lệch nếu chưa có thêm mẫu'}],
    answer:'a', why:{a:'Đúng. Người theo dõi trang tất nhiên đã biết thương hiệu; mẫu lệch theo hướng có thể đoán trước.',
      b:'Cỡ mẫu không sửa được lệch do cách chọn người; 3.000 fan vẫn lệch như 300 fan.',
      c:'Fan có xu hướng trả lời thiện cảm, không khắt khe hơn.',
      d:'Hướng lệch ở đây rất rõ: chọn từ người đã biết thì nhận biết bị đẩy lên.'} },
  { type:'mcq', stem:'Nhóm cần số cho hồ sơ gọi vốn trong hai tuần. Bạn chọn cách nào?',
    options:[{k:'a',t:'Chạy quảng cáo kéo thêm 1.000 phản hồi từ fanpage cho mẫu lớn hơn'},{k:'b',t:'Dùng số fanpage nhưng ghi chú nhỏ ở cuối trang'},
             {k:'c',t:'Bỏ khảo sát, dùng lượt theo dõi fanpage thay cho nhận biết'},{k:'d',t:'Khảo sát qua panel, có chỉ tiêu vùng, tuổi và lọc người dùng ngành hàng'}],
    answer:'d', why:{a:'Thêm phản hồi từ cùng nguồn lệch chỉ làm con số lệch trông chắc chắn hơn.',
      b:'Nhà đầu tư đọc con số chính; một con số lệch lớn làm mất uy tín khi bị hỏi lại.',
      c:'Lượt theo dõi đo quy mô trang, không đo tỉ lệ người trong thị trường biết mình.',
      d:'Đúng. Nguồn độc lập với thương hiệu, có chỉ tiêu và lọc ngành hàng mới cho con số đại diện.'} },
  { type:'calc', stem:'Thị trường mục tiêu có 60% ở TP.HCM, 40% ở Hà Nội. Mẫu 500 người, bạn đặt chỉ tiêu theo đúng tỉ lệ này. Cần bao nhiêu người trả lời ở Hà Nội?',
    unit:'người', ans:200, tol:0, wrong:[[300,'SAI_MAU_SO'],[250,'SAI_TINH_TOAN']], errors:['SAI_MAU_SO','SAI_TINH_TOAN'],
    steps:['Chỉ tiêu = cỡ mẫu × tỉ trọng vùng trong tổng thể.','500 × 40% = <b>200 người</b>.'] },
  { type:'mcq', stem:'Mẫu đã đủ chỉ tiêu vùng nhưng 70% người trả lời là sinh viên, trong khi tổng thể chỉ khoảng 20%. Bạn làm gì với kết quả?',
    options:[{k:'a',t:'Dùng luôn vì đã đạt chỉ tiêu vùng — yêu cầu quan trọng nhất'},{k:'b',t:'Gia trọng lại theo nhóm nghề hoặc lấy thêm mẫu cho nhóm thiếu'},
             {k:'c',t:'Loại hết sinh viên khỏi mẫu cho sạch dữ liệu'},{k:'d',t:'Nhân đôi mẫu với cùng nguồn để sai số giảm đi một nửa'}],
    answer:'b', why:{a:'Lệch nghề nghiệp lớn như vậy vẫn kéo số sai nếu sinh viên trả lời khác người đi làm.',
      b:'Đúng. Gia trọng hoặc bổ sung mẫu đưa cơ cấu về gần tổng thể.',
      c:'Sinh viên vẫn là 20% tổng thể; loại hết là tạo lệch theo hướng ngược lại.',
      d:'Lấy thêm từ cùng nguồn vẫn giữ nguyên 70% sinh viên.'} },
  { type:'mcq', stem:'Vì sao nên lọc người "không dùng ngành hàng" ra khỏi mẫu khảo sát thương hiệu dưỡng da?',
    options:[{k:'a',t:'Để con số nhận biết của mình cao lên cho đẹp báo cáo'},{k:'b',t:'Vì người không dùng thường trả lời lung tung và cố tình làm sai'},
             {k:'c',t:'Họ không nằm trong thị trường mà thương hiệu cạnh tranh'},{k:'d',t:'Vì pháp luật yêu cầu mọi khảo sát phải có câu hỏi lọc ngay đầu phiếu'}],
    answer:'c', why:{a:'Mục đích là đo đúng tổng thể, không phải làm số đẹp.',
      b:'Không có căn cứ cho rằng họ trả lời ẩu; lý do là họ nằm ngoài tổng thể.',
      c:'Đúng. Tổng thể là người mua ngành hàng; đo ngoài đó làm loãng con số.',
      d:'Câu lọc là lựa chọn thiết kế, không phải yêu cầu pháp lý chung.'} },
  { type:'mcq', stem:'Một chuỗi bánh mì phát phiếu khảo sát tại quầy của chính mình để đo nhận biết trong khu phố. Lỗi chính là gì?',
    options:[{k:'a',t:'Phiếu giấy lỗi thời, cần chuyển sang khảo sát online'},{k:'b',t:'Người đứng ở quầy đã là khách, nên nhận biết gần 100%'},
             {k:'c',t:'Khảo sát tại quầy khiến khách ngại, trả lời ngắn và thiếu chi tiết'},{k:'d',t:'Khu phố quá nhỏ nên không cần đo nhận biết'}],
    answer:'b', why:{a:'Hình thức phiếu không phải vấn đề; vấn đề là ai được hỏi.',
      b:'Đúng. Hỏi người đang đứng mua là hỏi người chắc chắn đã biết; cần hỏi người qua đường trong khu.',
      c:'Có thể có, nhưng lệch chọn mẫu là lỗi lớn hơn nhiều.',
      d:'Khu phố nhỏ vẫn là thị trường; đo để biết còn bao nhiêu người chưa biết.'} },
  { type:'mcq', stem:'Hai đợt khảo sát cách nhau sáu tháng, đợt đầu qua panel, đợt sau qua fanpage. Nhận biết tăng từ 22% lên 70%. Kết luận nào đúng?',
    options:[{k:'a',t:'Chiến dịch sáu tháng qua rất thành công, nên nhân rộng ngay'},{k:'b',t:'Nhận biết tăng thật nhưng có lẽ chỉ khoảng một nửa mức đó'},
             {k:'c',t:'Chưa so được vì đổi nguồn mẫu giữa hai đợt'},{k:'d',t:'Đợt đầu sai vì con số thấp hơn nhiều so với cảm nhận của nhóm'}],
    answer:'c', why:{a:'Mức tăng có thể đến hoàn toàn từ việc đổi sang hỏi fan.',
      b:'Không có cơ sở nào để chia đôi; khác nguồn thì không ước được phần tăng thật.',
      c:'Đúng. Theo dõi qua thời gian phải giữ cùng cách chọn mẫu và cùng câu hỏi.',
      d:'Đợt panel mới là đợt đại diện; cảm nhận của nhóm không phải thước đo.'} } ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:dl05-03', skill:'measure', read:'7 phút', t:'Nhận biết tăng 8 điểm sau chiến dịch: có phải nhờ quảng cáo?',
  situation:'Một hãng sữa hạt chạy chiến dịch video tám tuần ở Hà Nội. Khảo sát trước chiến dịch: nhận biết có nhắc 30%. Sau chiến dịch: 38%. Agency báo cáo "chiến dịch tăng nhận biết 8 điểm". Nhưng cùng thời gian, hãng cũng lên kệ thêm 200 cửa hàng tiện lợi và đối thủ lớn vừa rút quảng cáo.',
  concept:{ name:'Brand lift với nhóm đối chứng',
    body:'So trước – sau chỉ cho biết con số đã đổi, không cho biết <b>vì sao</b>. Mùa vụ, điểm bán mới, đối thủ, tin tức đều có thể đẩy con số. <b>Brand lift</b> đo phần tăng do chiến dịch bằng cách so hai nhóm giống nhau: nhóm <b>tiếp xúc</b> quảng cáo và nhóm <b>đối chứng</b> không tiếp xúc (khu vực không chạy, hoặc nhóm bị giữ lại không cho xem). Phần tăng do chiến dịch = mức tăng của nhóm tiếp xúc trừ mức tăng của nhóm đối chứng.' },
  example:'Hãng lấy Hải Phòng làm vùng đối chứng: cũng lên kệ cửa hàng mới, cũng có đối thủ rút quảng cáo, nhưng không chạy video. Nhận biết ở Hải Phòng tăng từ 28% lên 33%, tức 5 điểm. Hà Nội tăng 8 điểm. Phần do chiến dịch khoảng 8 − 5 = 3 điểm. Chiến dịch vẫn có tác dụng, nhưng nhỏ hơn nhiều so với báo cáo, và phần lớn mức tăng đến từ điểm bán mới.',
  takeaway:'Mức tăng do chiến dịch là mức tăng của nhóm xem trừ mức tăng của nhóm không xem, không phải sau trừ trước.',
  apply:'Chọn một chiến dịch sắp chạy. Nêu trong 60 giây vùng hoặc nhóm nào có thể làm đối chứng và vì sao nó giống vùng chạy.',
  mistakes:['Gán toàn bộ mức tăng trước – sau cho chiến dịch.','Chọn nhóm đối chứng khác hẳn nhóm tiếp xúc (thành phố lớn so với nông thôn).'],
  q:[
  { type:'mcq', stem:'Nhận biết tăng từ 30% lên 38% trong tám tuần có quảng cáo. Bạn đoán phần do quảng cáo là bao nhiêu?',
    options:[{k:'a',t:'Đúng 8 điểm, vì chiến dịch là thay đổi lớn nhất trong kỳ'},{k:'b',t:'Chưa biết, vì còn điểm bán mới và đối thủ rút quảng cáo'},
             {k:'c',t:'Hơn 8 điểm, vì còn hiệu ứng trễ chưa đo hết'},{k:'d',t:'Bằng 0, vì nhận biết chủ yếu do điểm bán tạo ra chứ không phải quảng cáo'}],
    answer:'b', why:{a:'Có ít nhất hai yếu tố khác cũng đẩy con số lên trong cùng kỳ.',
      b:'Đúng. Không có nhóm so sánh thì không tách được phần của chiến dịch.',
      c:'Hiệu ứng trễ có thể có, nhưng trước hết cần tách các yếu tố khác.',
      d:'Không có dữ kiện nào cho thấy quảng cáo không tác dụng.'} },
  { type:'mcq', stem:'Chiến dịch tiếp theo chạy ở TP.HCM. Bạn chọn nhóm đối chứng nào?',
    options:[{k:'a',t:'Một tỉnh miền Tây nhỏ, chi phí khảo sát rẻ hơn nhiều'},{k:'b',t:'Không cần đối chứng, chỉ cần khảo sát sau chiến dịch'},
             {k:'c',t:'Một thành phố lớn có điểm bán và đối thủ tương tự, không chạy chiến dịch'},{k:'d',t:'Người đã xem quảng cáo nhưng bấm bỏ qua sau 5 giây, coi như không xem'}],
    answer:'c', why:{a:'Tỉnh nhỏ có hành vi, điểm bán, mức nhận biết khác hẳn; không so được.',
      b:'Một điểm đo sau không cho biết thay đổi, càng không cho biết nguyên nhân.',
      c:'Đúng. Đối chứng phải giống vùng chạy ở mọi thứ trừ chiến dịch.',
      d:'Người bỏ qua vẫn tiếp xúc vài giây và họ khác người xem hết; không phải nhóm sạch.'} },
  { type:'calc', stem:'Vùng chạy quảng cáo: cân nhắc tăng từ 20% lên 29%. Vùng đối chứng: tăng từ 21% lên 25%. Phần tăng do chiến dịch là bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:5, tol:0.1, wrong:[[9,'SAI_TINH_TOAN'],[45,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_TINH_TOAN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Tăng ở vùng chạy: 29 − 20 = 9 điểm.','Tăng ở vùng đối chứng: 25 − 21 = 4 điểm.','Phần do chiến dịch: 9 − 4 = <b>5 điểm phần trăm</b>.'] },
  { type:'mcq', stem:'Nền tảng quảng cáo cung cấp "brand lift study": chia ngẫu nhiên người dùng thành nhóm xem và nhóm bị giữ lại. Ưu điểm chính là gì?',
    options:[{k:'a',t:'Hai nhóm giống nhau nhờ chia ngẫu nhiên, trừ việc xem quảng cáo'},{k:'b',t:'Nền tảng luôn cho kết quả cao hơn khảo sát độc lập, dễ trình sếp'},
             {k:'c',t:'Không cần đặt câu hỏi khảo sát nào'},{k:'d',t:'Đo được doanh số trực tiếp tại cửa hàng'}],
    answer:'a', why:{a:'Đúng. Chia ngẫu nhiên loại được hầu hết khác biệt giữa hai nhóm.',
      b:'Kết quả cao hay thấp không phải ưu điểm; nên đọc thận trọng vì nền tảng cũng là bên bán quảng cáo.',
      c:'Brand lift study vẫn hỏi một vài câu khảo sát ngắn trên nền tảng.',
      d:'Nó đo chỉ số thương hiệu như nhớ quảng cáo, nhận biết, cân nhắc, không đo doanh số cửa hàng.'} },
  { type:'mcq', stem:'Vùng đối chứng bất ngờ có một KOL lớn tự nhắc tới thương hiệu giữa kỳ đo. Điều này ảnh hưởng thế nào?',
    options:[{k:'a',t:'Làm phần tăng do chiến dịch bị ước quá cao'},{k:'b',t:'Không đáng kể vì chỉ một KOL, còn chiến dịch có hàng triệu lượt xem'},
             {k:'c',t:'Làm vùng đối chứng thành vùng chạy, nên cộng hai vùng lại'},{k:'d',t:'Có thể làm phần tăng do chiến dịch bị ước quá thấp'}],
    answer:'d', why:{a:'Đối chứng tăng thêm thì hiệu số nhỏ lại, tức bị ước thấp chứ không cao.',
      b:'Một KOL lớn đủ đẩy nhận biết vài điểm trong vùng; cần ghi nhận.',
      c:'Cộng hai vùng làm mất luôn nhóm so sánh.',
      d:'Đúng. Đối chứng bị "nhiễm" nên tăng nhiều hơn bình thường, hiệu số bị kéo xuống.'} },
  { type:'mcq', stem:'Chiến dịch có brand lift nhớ quảng cáo +12 điểm nhưng cân nhắc chỉ +1 điểm. Đọc thế nào?',
    options:[{k:'a',t:'Chiến dịch thành công vì 12 điểm là mức tăng lớn'},{k:'b',t:'Người ta nhớ quảng cáo nhưng không thấy lý do chọn thương hiệu'},
             {k:'c',t:'Khảo sát sai vì hai chỉ số phải tăng bằng nhau'},{k:'d',t:'Cần chạy thêm tám tuần nữa để cân nhắc đuổi kịp mức nhớ quảng cáo'}],
    answer:'b', why:{a:'Nhớ quảng cáo là tầng nông nhất; mục tiêu kinh doanh thường cần cân nhắc.',
      b:'Đúng. Quảng cáo gây chú ý nhưng thông điệp không chuyển thành ý định chọn.',
      c:'Các tầng thường tăng khác nhau; độ chênh là thông tin cần đọc.',
      d:'Kéo dài một thông điệp chưa thuyết phục chỉ lặp lại kết quả cũ.'} },
  { type:'mcq', stem:'Vì sao đo trước chiến dịch vẫn cần, dù đã có nhóm đối chứng?',
    options:[{k:'a',t:'Để kiểm tra hai nhóm vốn giống nhau lúc bắt đầu'},{k:'b',t:'Vì đo trước giúp chiến dịch có kết quả tốt hơn nhờ hiệu ứng khảo sát'},
             {k:'c',t:'Vì báo cáo cho sếp cần có ít nhất hai cột số liệu'},{k:'d',t:'Không cần, đo sau ở hai nhóm là đủ trong mọi trường hợp'}],
    answer:'a', why:{a:'Đúng. Nếu hai nhóm đã chênh từ đầu, chênh lệch sau chiến dịch có thể không phải do quảng cáo.',
      b:'Khảo sát không làm chiến dịch hiệu quả hơn.',
      c:'Lý do là phương pháp, không phải hình thức báo cáo.',
      d:'Khi không chia ngẫu nhiên (như chọn vùng), đo trước là cách duy nhất biết hai nhóm có khởi điểm giống nhau.'} } ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:dl05-04', skill:'measure', read:'6 phút', t:'Lượng tìm kiếm tên thương hiệu tăng: tín hiệu thật hay nhiễu?',
  situation:'Một chuỗi trà sữa mới ở Đà Nẵng không có tiền khảo sát định kỳ. Người sáng lập theo dõi lượng người tìm tên thương hiệu trên Google và TikTok. Tháng 5 khoảng 4.000 lượt, tháng 6 lên 9.000 lượt. Cùng tháng 6 có một bài báo nói về một vụ ngộ độc ở một quán trà sữa khác có tên gần giống.',
  concept:{ name:'Tìm kiếm tên thương hiệu như tín hiệu',
    body:'Người ta chỉ gõ tên một thương hiệu khi tên đó đã có trong đầu. Vì vậy lượng tìm kiếm tên thương hiệu (branded search) là một chỉ báo rẻ, cập nhật hàng tuần về <b>mức được nghĩ tới</b>. Nhưng nó có nhiễu: tên trùng hoặc gần giống, tin tức tiêu cực, khuyến mãi lớn làm người ta tìm mã giảm giá. Cách đọc: tách từ khoá theo biến thể tên, xem các cụm từ đi kèm (địa chỉ, menu, review, "ngộ độc"), so với cùng kỳ và với đối thủ, và luôn đối chiếu với một nguồn khác như lượt ghé quán.' },
  example:'Xem các cụm đi kèm: tháng 6 có 3.500 lượt tìm tên kèm "ngộ độc" và hầu hết từ ngày bài báo lên. Trừ đi, còn 5.500 lượt tìm với ý định thật (menu, địa chỉ, giờ mở), so với 3.800 lượt cùng loại tháng 5: tăng khoảng 45%, không phải 125%. Lượt khách đến quán tăng 40%, khớp với con số đã lọc. Người sáng lập dùng con số đã lọc để báo cáo và đặt cảnh báo cho các cụm tiêu cực.',
  takeaway:'Lượng tìm tên thương hiệu là tín hiệu tốt khi đã lọc nhiễu và đối chiếu với một nguồn độc lập.',
  apply:'Mở công cụ xu hướng tìm kiếm, gõ tên thương hiệu bạn quan tâm. Liệt kê ba cụm từ đi kèm phổ biến nhất và nói cụm nào là ý định mua.',
  mistakes:['Đọc tổng lượt tìm mà không xem các cụm đi kèm.','Coi mọi lượt tăng là tin tốt, kể cả khi do khủng hoảng.'],
  q:[
  { type:'mcq', stem:'Lượt tìm tên thương hiệu tăng từ 4.000 lên 9.000 trong một tháng. Phản ứng đầu tiên nên là gì?',
    options:[{k:'a',t:'Tăng ngân sách ngay vì thương hiệu đang lên, tranh thủ đà tăng trưởng'},{k:'b',t:'Bỏ qua, vì số tìm kiếm không phản ánh gì về thương hiệu cả'},
             {k:'c',t:'Xem các cụm từ đi kèm để biết người ta tìm vì lý do gì'},{k:'d',t:'Đổi tên thương hiệu để tránh trùng với quán khác'}],
    answer:'c', why:{a:'Chưa biết lý do tăng thì chưa nên hành động; có thể là tin xấu.',
      b:'Tìm kiếm tên là tín hiệu hữu ích, chỉ cần lọc nhiễu.',
      c:'Đúng. Cụm đi kèm cho biết ý định: tìm menu khác hẳn tìm tin tiêu cực.',
      d:'Quyết định quá lớn khi chưa đọc dữ liệu.'} },
  { type:'mcq', stem:'Bạn phải báo cáo tháng 6 cho nhà đầu tư. Bạn chọn trình bày con số nào?',
    options:[{k:'a',t:'9.000 lượt, tăng 125% — con số lớn và dễ hiểu nhất'},{k:'b',t:'Lượt tìm đã lọc cụm tiêu cực, kèm lượt khách đến quán'},
             {k:'c',t:'Không báo cáo tìm kiếm tháng này vì bị nhiễu'},{k:'d',t:'Lượt theo dõi TikTok vì nó ổn định và ít bị nhiễu hơn'}],
    answer:'b', why:{a:'Con số gộp phần lớn do tin của quán khác; bị hỏi lại sẽ mất uy tín.',
      b:'Đúng. Số đã lọc cộng một nguồn độc lập cho bức tranh đúng và bảo vệ được.',
      c:'Bỏ trống làm mất chuỗi theo dõi; lọc là đủ.',
      d:'Lượt theo dõi đo quy mô kênh, không đo mức được nghĩ tới trong tháng.'} },
  { type:'calc', stem:'Tháng 7 có 8.000 lượt tìm tên thương hiệu, trong đó 1.200 lượt kèm cụm tiêu cực và 800 lượt là tìm quán khác trùng tên. Tháng 7 cùng năm trước có 5.000 lượt tìm thật. Tìm kiếm thật tăng bao nhiêu phần trăm so với cùng kỳ?',
    unit:'%', ans:20, tol:0.5, wrong:[[60,'SAI_TINH_TOAN'],[37.5,'SAI_MAU_SO']], errors:['SAI_TINH_TOAN','SAI_MAU_SO'],
    steps:['Tìm thật tháng 7: 8.000 − 1.200 − 800 = 6.000.','Mức tăng: (6.000 − 5.000) ÷ 5.000 = 0,2 = <b>20%</b>.'] },
  { type:'mcq', stem:'Vì sao nên so lượt tìm với cùng kỳ năm trước thay vì chỉ so với tháng liền trước?',
    options:[{k:'a',t:'Vì tháng liền trước luôn có số liệu thiếu chính xác hơn'},{k:'b',t:'Vì công cụ tìm kiếm chỉ lưu dữ liệu theo năm'},
             {k:'c',t:'Vì nhà đầu tư thích so theo năm hơn so theo tháng'},{k:'d',t:'Vì nhiều ngành có mùa vụ, như trà sữa tăng mùa hè'}],
    answer:'d', why:{a:'Độ chính xác hai tháng như nhau; vấn đề là mùa vụ.',
      b:'Các công cụ cho xem theo tuần hoặc tháng.',
      c:'Sở thích người đọc không phải lý do phương pháp.',
      d:'Đúng. So cùng kỳ loại được phần tăng giảm do mùa.'} },
  { type:'mcq', stem:'Một hãng chạy khuyến mãi "nhập mã giảm 50%" và lượt tìm tên + "mã giảm giá" tăng gấp năm. Kết luận nào thận trọng nhất?',
    options:[{k:'a',t:'Mức được nghĩ tới của thương hiệu đã tăng gấp năm'},{k:'b',t:'Phần tăng chủ yếu do săn mã, cần tách khỏi tín hiệu thương hiệu'},
             {k:'c',t:'Khuyến mãi thất bại vì người ta chỉ tìm mã chứ không mua'},{k:'d',t:'Nên chạy khuyến mãi mỗi tháng để giữ lượt tìm ở mức cao như thế này'}],
    answer:'b', why:{a:'Người săn mã tìm theo khuyến mãi; khi hết mã, lượt tìm thường rơi lại.',
      b:'Đúng. Tìm mã là ý định do khuyến mãi tạo ra, không phải sức hút thương hiệu bền.',
      c:'Không có dữ kiện về doanh số; tìm mã không có nghĩa là không mua.',
      d:'Đẩy lượt tìm bằng giảm giá liên tục làm mỏng lãi và dạy khách chờ mã.'} },
  { type:'mcq', stem:'Một thương hiệu tên là từ thông dụng ("Mộc", "Nắng"). Khó khăn khi dùng lượt tìm tên là gì?',
    options:[{k:'a',t:'Lượt tìm lẫn với người tìm nghĩa thông thường của từ'},{k:'b',t:'Công cụ tìm kiếm không cho đo từ ngắn dưới ba chữ cái'},
             {k:'c',t:'Tên thông dụng luôn có lượt tìm thấp hơn tên lạ'},{k:'d',t:'Không có khó khăn gì vì tên dễ nhớ thì người ta tìm đúng hơn'}],
    answer:'a', why:{a:'Đúng. Cần đo theo cụm như tên + ngành hàng ("Mộc cà phê") để lọc.',
      b:'Công cụ vẫn đo được từ ngắn; vấn đề là nghĩa lẫn.',
      c:'Tên thông dụng thường có lượt tìm cao hơn, nhưng phần lớn không liên quan thương hiệu.',
      d:'Dễ nhớ không giải quyết chuyện người khác tìm cùng từ với nghĩa khác.'} },
  { type:'mcq', stem:'Lượt tìm tên tăng 30% nhưng khảo sát quý cho thấy nhận biết không đổi. Cách giải thích hợp lý nhất?',
    options:[{k:'a',t:'Khảo sát chắc chắn sai vì tìm kiếm là dữ liệu hành vi thật'},{k:'b',t:'Tìm kiếm chắc chắn sai vì khảo sát mới là chuẩn ngành'},
             {k:'c',t:'Người đã biết tìm nhiều hơn; số người biết chưa đổi'},{k:'d',t:'Hai con số không liên quan gì, nên chọn một để theo dõi'}],
    answer:'c', why:{a:'Hai nguồn đo hai thứ khác nhau; không cần có một bên sai.',
      b:'Khảo sát cũng có sai số; không bên nào tự động đúng.',
      c:'Đúng. Tìm kiếm đo mức được nghĩ tới trong nhóm đã biết; nhận biết đo độ rộng.',
      d:'Hai nguồn bổ sung cho nhau; bỏ một là mất góc nhìn.'} } ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:dl05-05', skill:'measure', read:'7 phút', t:'Share of search 18% nói gì về thị phần năm sau?',
  situation:'Một hãng bột giặt nội địa muốn biết mình đang lên hay xuống so với các hãng lớn mà không đợi báo cáo thị phần sáu tháng một lần. Trong quý, lượt tìm tên năm hãng chính cộng lại là 500.000; hãng mình chiếm 90.000. Quý trước là 70.000 trên tổng 480.000. Thị phần doanh số hiện khoảng 12%.',
  concept:{ name:'Share of search',
    body:'<b>Share of search</b> = lượt tìm tên thương hiệu ÷ tổng lượt tìm tên của các thương hiệu trong cùng ngành hàng. Vì tìm kiếm phản ánh mức được nghĩ tới, share of search thường đi trước thị phần doanh số: khi nó cao hơn thị phần hiện tại, thương hiệu có đà tăng; khi thấp hơn, có nguy cơ mất thị phần. Điều kiện để đọc đúng: cùng một rổ thương hiệu mỗi kỳ, lọc nhiễu tên trùng, và dùng như một <b>chỉ báo xu hướng</b> chứ không phải dự báo chính xác.' },
  example:'Quý trước: 70.000 ÷ 480.000 ≈ 14,6%. Quý này: 90.000 ÷ 500.000 = 18%. Share of search tăng khoảng 3,4 điểm và đang cao hơn thị phần doanh số 12% khoảng 6 điểm. Đây là tín hiệu đà tăng. Hãng không hứa "thị phần sẽ lên 18%" mà đặt kế hoạch theo dõi: nếu share of search giữ trên 16% thêm hai quý, mở rộng phân phối để đón nhu cầu.',
  takeaway:'Share of search cao hơn thị phần là tín hiệu đà tăng; thấp hơn là lời cảnh báo sớm.',
  apply:'Chọn một ngành hàng và năm thương hiệu chính. Ước lượng share of search của từng hãng và nói hãng nào đang có khoảng cách lớn nhất với thị phần.',
  mistakes:['Nhầm share of search với thị phần doanh số.','Thay đổi rổ thương hiệu giữa các kỳ khiến con số nhảy giả.'],
  q:[
  { type:'mcq', stem:'Share of search 18%, thị phần 12%. Bạn đoán điều gì có khả năng xảy ra?',
    options:[{k:'a',t:'Thị phần sẽ tăng đúng lên 18% trong quý tới'},{k:'b',t:'Thị phần sẽ giảm vì tìm kiếm cao do khách phàn nàn nhiều hơn'},
             {k:'c',t:'Hai con số không liên quan gì tới nhau'},{k:'d',t:'Thị phần có đà tăng, nhưng mức và thời điểm chưa chắc'}],
    answer:'d', why:{a:'Share of search là chỉ báo xu hướng, không phải dự báo con số chính xác.',
      b:'Không có dữ kiện về phàn nàn; nếu có thì phải lọc trước khi tính.',
      c:'Share of search thường đi trước thị phần vì phản ánh mức được nghĩ tới.',
      d:'Đúng. Khoảng cách dương cho thấy đà tăng, cần theo dõi thêm để xác nhận.'} },
  { type:'mcq', stem:'Quý tới có một hãng mới nổi được thêm vào thị trường. Bạn chọn xử lý rổ thương hiệu thế nào?',
    options:[{k:'a',t:'Thêm hãng mới, tính lại cả các quý trước theo rổ mới'},{k:'b',t:'Thêm hãng mới từ quý tới, giữ nguyên số liệu các quý trước để khỏi mất thời gian'},
             {k:'c',t:'Không thêm, vì hãng mới còn nhỏ'},{k:'d',t:'Bỏ luôn chỉ số vì rổ thay đổi nên không còn so được với quá khứ'}],
    answer:'a', why:{a:'Đúng. Tính lại chuỗi theo cùng rổ để so kỳ này với kỳ trước công bằng.',
      b:'Mẫu số đổi giữa chừng làm share of search của mình tụt giả.',
      c:'Nếu hãng mới đang lấy khách, bỏ qua là mất tín hiệu quan trọng nhất.',
      d:'Rổ đổi thì tính lại chuỗi, không cần bỏ chỉ số.'} },
  { type:'calc', stem:'Rổ bốn hãng có tổng 400.000 lượt tìm tên trong quý. Hãng bạn có 60.000 lượt. Thị phần doanh số là 20%. Share of search thấp hơn thị phần bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:5, tol:0.1, wrong:[[15,'SAI_TINH_TOAN'],[25,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_TINH_TOAN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Share of search = 60.000 ÷ 400.000 = 15%.','Chênh với thị phần: 20 − 15 = <b>5 điểm phần trăm</b> (thấp hơn).'] },
  { type:'calc', stem:'Quý trước hãng bạn có 70.000 trên tổng 500.000 lượt tìm. Quý này 84.000 trên tổng 600.000. Share of search thay đổi bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:0, tol:0.1, wrong:[[20,'NHAM_SO_TUYET_DOI'],[14,'SAI_TINH_TOAN']], errors:['NHAM_SO_TUYET_DOI'],
    steps:['Quý trước: 70.000 ÷ 500.000 = 14%.','Quý này: 84.000 ÷ 600.000 = 14%.','Thay đổi: <b>0 điểm</b> — lượt tìm tăng 20% chỉ vì cả ngành tăng.'] },
  { type:'mcq', stem:'Share of search và share of voice khác nhau thế nào?',
    options:[{k:'a',t:'Là một, chỉ khác tên gọi giữa các agency quảng cáo'},{k:'b',t:'Search đo nhu cầu trong đầu khách; voice đo phần quảng cáo mình phát ra'},
             {k:'c',t:'Search đo phần quảng cáo, voice đo nhu cầu'},{k:'d',t:'Share of voice chỉ dùng cho truyền hình còn search chỉ dùng cho online'}],
    answer:'b', why:{a:'Hai chỉ số đo hai phía khác nhau của cùng câu chuyện.',
      b:'Đúng. Voice là đầu vào (mình nói bao nhiêu), search là đầu ra (khách nghĩ tới mình bao nhiêu).',
      c:'Ngược nghĩa.',
      d:'Share of voice đo trên mọi kênh; phân biệt không nằm ở kênh.'} },
  { type:'mcq', stem:'Một hãng xe máy điện có share of search tăng vọt trong tháng có tin pin bị lỗi. Cách dùng chỉ số đúng là gì?',
    options:[{k:'a',t:'Báo cáo đà tăng như bình thường'},{k:'b',t:'Ngừng đo share of search vĩnh viễn'},
             {k:'c',t:'Lọc các lượt tìm gắn với sự cố trước khi tính share of search'},{k:'d',t:'Cộng thêm lượt tìm của đối thủ để cân bằng, cho con số khỏi nhảy vọt bất thường'}],
    answer:'c', why:{a:'Tìm vì sự cố không phải nhu cầu mua; tính gộp là tự lừa mình.',
      b:'Chỉ một tháng nhiễu; lọc là đủ.',
      c:'Đúng. Share of search chỉ có nghĩa khi đo nhu cầu, không đo sự tò mò về tin xấu.',
      d:'Chỉnh số đối thủ tuỳ tiện làm hỏng cả chuỗi.'} },
  { type:'mcq', stem:'Vì sao share of search phù hợp với doanh nghiệp nhỏ không có ngân sách khảo sát?',
    options:[{k:'a',t:'Vì nó chính xác hơn mọi khảo sát, kể cả khảo sát lớn'},{k:'b',t:'Vì nó đo được doanh số của đối thủ một cách chính xác'},
             {k:'c',t:'Dữ liệu gần như miễn phí, cập nhật hàng tuần'},{k:'d',t:'Vì pháp luật không cho doanh nghiệp nhỏ tự làm khảo sát'}],
    answer:'c', why:{a:'Nó không thay được mọi khảo sát; nó rẻ và nhanh, không nhất thiết chính xác hơn.',
      b:'Nó không đo doanh số; chỉ đo mức được tìm.',
      c:'Đúng. Rẻ, nhanh và so được với đối thủ là lợi thế lớn nhất.',
      d:'Không có quy định chung như vậy; lý do là chi phí.'} } ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:dl05-06', skill:'measure', read:'7 phút', t:'NPS 45: nên treo lên tường hay nên đọc kỹ hơn?',
  situation:'Một chuỗi phòng tập ở Hà Nội gửi câu hỏi "Bạn có sẵn lòng giới thiệu chúng tôi cho bạn bè không, 0–10?" qua tin nhắn sau buổi tập đầu tiên. 1.000 người trả lời: 55% chấm 9–10, 35% chấm 7–8, 10% chấm 0–6. NPS 45. Ban giám đốc muốn thưởng cho quản lý chi nhánh theo NPS từ quý sau.',
  concept:{ name:'NPS: cách dùng và cách lạm dụng',
    body:'<b>NPS</b> = % người ủng hộ (9–10) − % người phản đối (0–6). Nó dễ hiểu và so được theo thời gian. Nhưng nó dễ bị lạm dụng: hỏi ở thời điểm vui nhất (vừa xong buổi đầu), chỉ hỏi người còn ở lại, gắn thưởng khiến nhân viên xin điểm, và đọc một con số mà không đọc lý do. Dùng đúng: hỏi cùng thời điểm trong hành trình, gồm cả người đã rời đi, luôn kèm câu hỏi mở "vì sao", và theo dõi <b>xu hướng</b> cùng với hành vi thật như tỉ lệ gia hạn.' },
  example:'NPS 55 − 10 = 45 đo sau buổi đầu, lúc khách còn hào hứng. Hỏi lại ở tháng thứ ba với cả người đã huỷ: NPS còn 12. Câu hỏi mở cho thấy lý do chính là "giờ cao điểm hết máy". Nếu gắn thưởng theo NPS sau buổi đầu, quản lý sẽ tập trung chăm buổi đầu và xin điểm, trong khi vấn đề thật là quá tải giờ cao điểm. Chuỗi giữ NPS làm chỉ báo, đo ở tháng thứ ba, và thưởng theo tỉ lệ gia hạn.',
  takeaway:'NPS có ích khi đo đúng lúc, đúng người, kèm lý do; gắn thưởng vào nó là mời người ta xin điểm.',
  apply:'Viết lại bộ câu hỏi NPS cho một dịch vụ bạn biết: hỏi lúc nào, hỏi ai, và câu hỏi mở đi kèm là gì.',
  mistakes:['Hỏi NPS ngay sau trải nghiệm vui nhất rồi coi đó là sức khoẻ thương hiệu.','Gắn thưởng cá nhân vào NPS khiến nhân viên xin điểm.'],
  q:[
  { type:'mcq', stem:'NPS 45 đo sau buổi tập đầu tiên. Bạn đoán NPS ở tháng thứ ba sẽ thế nào?',
    options:[{k:'a',t:'Cao hơn, vì khách đã quen phòng tập và có thêm bạn tập'},{k:'b',t:'Có thể thấp hơn nhiều, vì hào hứng ban đầu đã qua'},
             {k:'c',t:'Giữ nguyên vì NPS là chỉ số ổn định'},{k:'d',t:'Không đo được vì khách tháng ba không trả lời'}],
    answer:'b', why:{a:'Có thể với người ở lại, nhưng người không hài lòng thường đã rời đi hoặc chấm thấp.',
      b:'Đúng. Buổi đầu là lúc cảm xúc tốt nhất; trải nghiệm thật lộ ra sau vài tuần.',
      c:'NPS thay đổi mạnh theo thời điểm hỏi.',
      d:'Vẫn đo được; chỉ cần gửi lại cho cả người đã huỷ.'} },
  { type:'mcq', stem:'Ban giám đốc muốn thưởng quản lý chi nhánh theo NPS. Bạn đề xuất gì?',
    options:[{k:'a',t:'Đồng ý, và nâng mục tiêu lên 60 để tạo động lực cho quản lý'},{k:'b',t:'Đồng ý, nhưng chỉ thưởng khi NPS trên 50'},
             {k:'c',t:'Bỏ NPS, chỉ theo dõi doanh thu chi nhánh'},{k:'d',t:'Thưởng theo tỉ lệ gia hạn; giữ NPS làm chỉ báo, đo ở tháng ba'}],
    answer:'d', why:{a:'Mục tiêu cao hơn chỉ tăng áp lực xin điểm, không sửa vấn đề thật.',
      b:'Ngưỡng nào thì cũng biến NPS thành con số để đạt thay vì để học.',
      c:'NPS vẫn có ích để phát hiện lý do; chỉ không nên gắn thưởng.',
      d:'Đúng. Gia hạn là hành vi thật, khó xin; NPS để đọc lý do.'} },
  { type:'calc', stem:'1.200 người trả lời: 480 chấm 9–10, 420 chấm 7–8, 300 chấm 0–6. NPS là bao nhiêu?',
    unit:'điểm', ans:15, tol:0.1, wrong:[[40,'SAI_TINH_TOAN'],[180,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN','NHAM_SO_TUYET_DOI'],
    steps:['% ủng hộ = 480 ÷ 1.200 = 40%. % phản đối = 300 ÷ 1.200 = 25%.','NPS = 40 − 25 = <b>15</b>. Nhóm 7–8 không cộng vào đâu.'] },
  { type:'mcq', stem:'Chi nhánh A có NPS 30 với 20 người trả lời; chi nhánh B có NPS 25 với 400 người trả lời. Nhận định nào đúng?',
    options:[{k:'a',t:'A tốt hơn B 5 điểm, nên nhân rộng cách làm của A'},{k:'b',t:'B tốt hơn vì nhiều người trả lời hơn'},
             {k:'c',t:'Với 20 người, NPS của A dao động quá rộng để so'},{k:'d',t:'Cả hai đều kém vì NPS dưới 50 là thất bại theo chuẩn thế giới'}],
    answer:'c', why:{a:'Mẫu 20 người, một người đổi ý là NPS nhảy 5 điểm; chênh 5 điểm chưa có nghĩa.',
      b:'Nhiều người trả lời làm con số chắc hơn, không làm nó tốt hơn.',
      c:'Đúng. Mẫu nhỏ khiến NPS dao động mạnh; cần gộp nhiều tháng.',
      d:'Không có chuẩn chung; NPS phải so trong ngành và theo thời gian.'} },
  { type:'mcq', stem:'NPS tăng từ 20 lên 35 sau khi đổi cách gửi: trước gửi cho mọi hội viên, nay chỉ gửi cho người đến tập trong tuần. Đọc thế nào?',
    options:[{k:'a',t:'Có thể chỉ do bỏ người ít đến, vốn hay chấm thấp'},{k:'b',t:'Dịch vụ đã cải thiện rõ trong kỳ, xứng đáng khen thưởng'},
             {k:'c',t:'Người ít đến trả lời thiếu khách quan nên loại là đúng'},{k:'d',t:'Tăng 15 điểm là quá lớn nên chắc chắn là lỗi phần mềm khảo sát'}],
    answer:'a', why:{a:'Đúng. Đổi đối tượng hỏi là đổi phép đo; con số mới không so được với cũ.',
      b:'Chưa tách được phần do đổi mẫu.',
      c:'Người ít đến là tín hiệu sắp rời đi; loại họ là che mất vấn đề.',
      d:'Không cần giả định lỗi phần mềm khi đã có lý do rõ.'} },
  { type:'mcq', stem:'Nhân viên lễ tân nói với khách "anh chị chấm giúp em 10 điểm nhé". Hậu quả lớn nhất là gì?',
    options:[{k:'a',t:'Khách khó chịu nên chấm thấp hơn, kéo NPS xuống'},{k:'b',t:'Chi phí khảo sát tăng vì phải gửi lại'},
             {k:'c',t:'NPS mất tác dụng báo hiệu vấn đề thật'},{k:'d',t:'Không sao, vì khách hài lòng thì đằng nào cũng chấm cao'}],
    answer:'c', why:{a:'Thường khách chiều theo và chấm cao; vấn đề là số bị đẩy lên.',
      b:'Chi phí không phải hậu quả chính.',
      c:'Đúng. Điểm xin được không còn phản ánh trải nghiệm, nên không phát hiện được lỗi.',
      d:'Chính khách không hài lòng cũng chấm cao khi bị xin, nên con số che mất họ.'} },
  { type:'mcq', stem:'Phần nào của khảo sát NPS thường có giá trị nhất để cải thiện dịch vụ?',
    options:[{k:'a',t:'Câu hỏi mở "vì sao bạn chấm điểm đó?"'},{k:'b',t:'Con số NPS tổng, vì nó so được với các đối thủ trong cùng ngành'},
             {k:'c',t:'Số người chấm đúng 10 điểm'},{k:'d',t:'Tỉ lệ người mở tin nhắn khảo sát'}],
    answer:'a', why:{a:'Đúng. Lý do cho biết phải sửa gì; con số chỉ cho biết có vấn đề.',
      b:'NPS đối thủ hiếm khi đo cùng cách nên khó so; và con số không chỉ ra việc cần làm.',
      c:'Đếm điểm 10 không chỉ ra điều gì cần sửa.',
      d:'Tỉ lệ mở đo kênh gửi, không đo trải nghiệm.'} } ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:dl05-07', skill:'measure', read:'6 phút', t:'Lượt nhắc trên mạng xã hội tăng gấp ba: mừng hay lo?',
  situation:'Một hãng bánh trung thu dùng công cụ lắng nghe mạng xã hội. Tháng 8 có 3.000 lượt nhắc tên thương hiệu, tháng 9 lên 9.000. Báo cáo tự động chấm 70% "trung tính", 20% "tích cực", 10% "tiêu cực". Trưởng nhóm muốn báo cáo "thảo luận tăng 200%, đa phần tích cực".',
  concept:{ name:'Lắng nghe mạng xã hội và tỉ lệ cảm xúc',
    body:'Lắng nghe mạng xã hội đếm lượt nhắc và phân loại cảm xúc. Hai điều cần nhớ. Một, <b>lượng</b> không nói lên chất: lượt nhắc tăng có thể do quà tặng, do mùa vụ, hoặc do một phốt. Hai, <b>máy chấm cảm xúc</b> tiếng Việt hay sai với tiếng lóng, mỉa mai, viết tắt; nhóm "trung tính" thường là rổ chứa mọi thứ máy không hiểu. Cách đọc: tính <b>tỉ lệ ròng</b> = (tích cực − tiêu cực) ÷ (tích cực + tiêu cực), đọc tay một mẫu ngẫu nhiên để kiểm tra máy, và theo dõi chủ đề của nhóm tiêu cực.' },
  example:'Đọc tay 200 bài ngẫu nhiên trong nhóm "trung tính": khoảng 25% thực ra tiêu cực, kiểu "bánh năm nay nhỏ hẳn, giá thì y chang, hay ghê". Điều chỉnh: tích cực 20%, tiêu cực 10% + 70% × 25% ≈ 27,5%. Tỉ lệ ròng từ (20 − 10) ÷ 30 ≈ +33% chuyển thành (20 − 27,5) ÷ 47,5 ≈ −16%. Chủ đề tiêu cực chính: kích cỡ bánh giảm. Báo cáo đúng là "thảo luận tăng mạnh mùa vụ, cảm xúc ròng âm vì cảm nhận bánh nhỏ đi".',
  takeaway:'Đếm lượt nhắc là chưa đủ: kiểm tra máy chấm bằng mắt người và đọc chủ đề của nhóm tiêu cực.',
  apply:'Tìm 20 bình luận gần nhất về một thương hiệu bạn chọn. Tự phân loại tích cực, tiêu cực, trung tính và tính tỉ lệ ròng.',
  mistakes:['Tin tuyệt đối vào nhãn cảm xúc tự động với tiếng Việt.','Báo cáo lượt nhắc tăng như tin tốt mà không so với mùa vụ.'],
  q:[
  { type:'mcq', stem:'Lượt nhắc tăng gấp ba vào tháng 9. Bạn đoán lý do lớn nhất là gì?',
    options:[{k:'a',t:'Chiến dịch tháng 8 đã tạo hiệu ứng lan toả mạnh'},{k:'b',t:'Có một phốt lớn vì lượt nhắc tăng bất thường'},
             {k:'c',t:'Công cụ lắng nghe đã được nâng cấp, quét rộng hơn'},{k:'d',t:'Tháng 9 là mùa trung thu, cả ngành đều tăng'}],
    answer:'d', why:{a:'Có thể góp phần, nhưng chưa có bằng chứng; mùa vụ là lý do hiển nhiên hơn.',
      b:'Phốt là khả năng cần kiểm tra, không phải giả định đầu tiên.',
      c:'Có thể, nhưng không có dữ kiện về việc đổi công cụ.',
      d:'Đúng. Với bánh trung thu, tháng 9 là cao điểm; phải so với cùng kỳ và đối thủ.'} },
  { type:'mcq', stem:'Trưởng nhóm muốn báo cáo "đa phần tích cực". Bạn làm gì trước khi gửi báo cáo?',
    options:[{k:'a',t:'Gửi luôn vì công cụ đã chấm tự động toàn bộ, không cần can thiệp gì thêm'},{k:'b',t:'Đọc tay mẫu ngẫu nhiên trong nhóm trung tính và tiêu cực để kiểm tra'},
             {k:'c',t:'Bỏ nhóm trung tính, chỉ báo tích cực và tiêu cực'},{k:'d',t:'Chuyển sang công cụ khác cho kết quả tích cực cao hơn'}],
    answer:'b', why:{a:'Máy chấm tiếng Việt hay sai với mỉa mai; gửi luôn là rủi ro.',
      b:'Đúng. Vài trăm bài đọc tay đủ để biết máy lệch bao nhiêu và theo hướng nào.',
      c:'70% dữ liệu nằm ở nhóm trung tính; bỏ đi là bỏ phần lớn bằng chứng.',
      d:'Chọn công cụ theo kết quả mong muốn là tự lừa mình.'} },
  { type:'calc', stem:'Tháng này có 600 lượt tích cực, 200 lượt tiêu cực và 1.200 lượt trung tính. Tỉ lệ cảm xúc ròng = (tích cực − tiêu cực) ÷ (tích cực + tiêu cực) là bao nhiêu phần trăm?',
    unit:'%', ans:50, tol:0.5, wrong:[[20,'SAI_MAU_SO'],[400,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO','NHAM_SO_TUYET_DOI'],
    steps:['Tử số: 600 − 200 = 400.','Mẫu số chỉ gồm lượt có cảm xúc: 600 + 200 = 800.','400 ÷ 800 = <b>50%</b>.'] },
  { type:'mcq', stem:'Bình luận "Giao hàng nhanh thật sự, đặt hôm nay tháng sau mới tới" bị máy chấm tích cực. Bài học là gì?',
    options:[{k:'a',t:'Máy không nhận ra mỉa mai; cần đọc tay kiểm tra'},{k:'b',t:'Khách này thực ra khen, chỉ viết hơi dài dòng và khó hiểu một chút'},
             {k:'c',t:'Nên bỏ hẳn lắng nghe mạng xã hội'},{k:'d',t:'Nên dạy khách viết rõ ràng hơn qua tin nhắn chăm sóc'}],
    answer:'a', why:{a:'Đúng. Mỉa mai là lỗi điển hình; đọc tay mẫu giúp ước lượng sai số.',
      b:'Câu này là chê giao chậm theo lối mỉa mai.',
      c:'Công cụ vẫn có ích để đếm và lọc chủ đề; chỉ cần kiểm tra lại.',
      d:'Không kiểm soát được cách khách viết; phải sửa cách đọc.'} },
  { type:'mcq', stem:'Lượt nhắc tiêu cực tăng từ 100 lên 400 trong tuần, chủ đề chính là "hộp quà bị móp khi giao". Hành động phù hợp nhất?',
    options:[{k:'a',t:'Chờ hết mùa rồi đánh giá lại toàn bộ'},{k:'b',t:'Chạy thêm quảng cáo tích cực để làm loãng các bình luận chê'},
             {k:'c',t:'Chuyển ngay chủ đề cho vận hành sửa đóng gói'},{k:'d',t:'Ẩn các bình luận tiêu cực trên fanpage của hãng'}],
    answer:'c', why:{a:'Mùa bánh ngắn; chờ hết mùa là mất cả mùa.',
      b:'Quảng cáo không sửa hộp móp; khách vẫn nhận hộp móp.',
      c:'Đúng. Lắng nghe có giá trị khi chủ đề cụ thể đến tay người sửa được.',
      d:'Ẩn bình luận không sửa vấn đề và dễ tạo thêm phản ứng.'} },
  { type:'mcq', stem:'Vì sao nên theo dõi tỉ lệ ròng thay vì chỉ số lượt tích cực?',
    options:[{k:'a',t:'Vì lượt tích cực luôn bị máy chấm sai nhiều hơn lượt tiêu cực'},{k:'b',t:'Tích cực có thể tăng chỉ vì tổng lượt nhắc tăng'},
             {k:'c',t:'Vì tỉ lệ ròng luôn dương nên dễ báo cáo'},{k:'d',t:'Vì công cụ không đếm được lượt tích cực riêng'}],
    answer:'b', why:{a:'Máy sai ở cả hai phía; lý do là tính theo tỉ lệ.',
      b:'Đúng. Số tuyệt đối chạy theo quy mô thảo luận; tỉ lệ ròng cho biết cán cân.',
      c:'Tỉ lệ ròng có thể âm, như trong ví dụ bánh bị nhỏ đi.',
      d:'Công cụ đếm được; vấn đề là đọc số tuyệt đối dễ sai.'} },
  { type:'mcq', stem:'Một hãng thấy lượt nhắc rất ít dù doanh số ổn định (nước chấm, giấy vệ sinh). Kết luận đúng nhất?',
    options:[{k:'a',t:'Thương hiệu đang yếu dần, cần chạy chiến dịch viral gấp'},{k:'b',t:'Công cụ lắng nghe bị lỗi, cần đổi nhà cung cấp'},
             {k:'c',t:'Ngành ít được bàn luận; lắng nghe không phải thước đo chính'},{k:'d',t:'Hãng nên thuê người bình luận để có dữ liệu lắng nghe đủ lớn mà đọc'}],
    answer:'c', why:{a:'Ít bàn luận không có nghĩa là yếu; nhiều ngành thiết yếu ít ai đăng bài.',
      b:'Không có dấu hiệu lỗi công cụ.',
      c:'Đúng. Mỗi ngành cần chọn thước đo hợp; ở đây khảo sát và tìm kiếm có ích hơn.',
      d:'Tạo bình luận giả làm hỏng dữ liệu và gây rủi ro uy tín.'} } ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:dl05-08', skill:'measure', read:'7 phút', t:'Nhận biết giảm từ 34% xuống 30%: báo động hay dao động?',
  situation:'Một hãng dầu gội nội địa khảo sát nhận biết mỗi quý với 250 người. Quý 2: 34%. Quý 3: 30%. Trưởng phòng marketing chuẩn bị xin thêm ngân sách để "cứu nhận biết đang giảm 4 điểm". Bạn được hỏi: con số này có đủ tin để hành động không?',
  concept:{ name:'Sai số khảo sát khi mẫu nhỏ',
    body:'Một tỉ lệ đo từ mẫu luôn có <b>sai số</b>. Ước lượng nhanh với độ tin cậy 95%: sai số ≈ 1,96 × căn bậc hai của p × (1 − p) ÷ n, với p là tỉ lệ, n là cỡ mẫu. Với p khoảng 30% và n = 250, sai số khoảng ±5,7 điểm. Khi so hai đợt, chênh lệch cần lớn hơn hẳn mức đó mới đáng tin. Muốn giảm sai số một nửa, cỡ mẫu phải tăng <b>gấp bốn</b>. Vì vậy mẫu nhỏ chỉ nên dùng để phát hiện thay đổi lớn, hoặc gộp nhiều kỳ lại để đọc xu hướng.' },
  example:'Với n = 250 và p ≈ 32%: sai số ≈ 1,96 × √(0,32 × 0,68 ÷ 250) ≈ 1,96 × 0,0295 ≈ ±5,8 điểm. Mức giảm 4 điểm nằm trong vùng dao động bình thường. Bạn đề xuất: không xin tiền dựa trên một quý, xem thêm tìm kiếm tên thương hiệu (không đổi) và doanh số (không đổi), và nâng mẫu lên 1.000 từ quý sau để sai số còn khoảng ±2,9 điểm.',
  takeaway:'Trước khi phản ứng với một mức thay đổi, hãy so nó với sai số của mẫu.',
  apply:'Lấy một khảo sát bạn từng thấy. Tính sai số ước lượng từ tỉ lệ và cỡ mẫu, rồi nói chênh lệch được báo cáo có vượt sai số không.',
  mistakes:['Phản ứng với chênh lệch nhỏ hơn sai số.','Nghĩ tăng gấp đôi mẫu thì sai số giảm một nửa.'],
  q:[
  { type:'mcq', stem:'Nhận biết giảm 4 điểm với mẫu 250 người mỗi quý. Bạn đoán điều này đáng tin tới mức nào?',
    options:[{k:'a',t:'Rất đáng tin vì 4 điểm là mức giảm hơn 10% so với quý trước'},{k:'b',t:'Chắc chắn là sai vì nhận biết không thể giảm trong một quý'},
             {k:'c',t:'Có thể chỉ là dao động do mẫu nhỏ'},{k:'d',t:'Đáng tin nếu khảo sát được làm bởi công ty lớn'}],
    answer:'c', why:{a:'Đọc theo phần trăm tương đối làm mức giảm trông lớn; cần so với sai số.',
      b:'Nhận biết có thể giảm thật; chỉ là chưa đủ bằng chứng.',
      c:'Đúng. Với 250 người, dao động ngẫu nhiên có thể tới khoảng ±6 điểm.',
      d:'Công ty lớn không làm giảm sai số do cỡ mẫu.'} },
  { type:'mcq', stem:'Trưởng phòng muốn xin ngân sách "cứu nhận biết". Bạn làm gì?',
    options:[{k:'a',t:'Chưa xin; đối chiếu nguồn khác và nâng cỡ mẫu từ quý sau'},{k:'b',t:'Xin ngay để phòng khi giảm thật, vì mất nhận biết rất khó lấy lại'},
             {k:'c',t:'Đổi công ty khảo sát vì kết quả quý này có vấn đề'},{k:'d',t:'Bỏ khảo sát quý, chỉ làm một lần mỗi năm cho tiết kiệm chi phí'}],
    answer:'a', why:{a:'Đúng. Chênh lệch nằm trong sai số; cần thêm bằng chứng trước khi chi.',
      b:'Chi tiền dựa trên nhiễu là lãng phí và làm mất niềm tin vào dữ liệu.',
      c:'Kết quả không có vấn đề; đó là giới hạn của mẫu nhỏ.',
      d:'Đo thưa hơn không sửa sai số; cần mẫu lớn hơn hoặc gộp kỳ.'} },
  { type:'calc', stem:'Khảo sát 400 người, 50% nhận biết. Ước lượng sai số ở độ tin cậy 95% theo công thức 1,96 × √(p × (1 − p) ÷ n) là bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:4.9, tol:0.1, wrong:[[2.5,'SAI_TINH_TOAN'],[0.0625,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['p × (1 − p) = 0,5 × 0,5 = 0,25. Chia n: 0,25 ÷ 400 = 0,000625.','Căn bậc hai: 0,025. Nhân 1,96: 0,049.','Sai số ≈ <b>±4,9 điểm phần trăm</b>.'] },
  { type:'calc', stem:'Mẫu 300 người cho sai số khoảng ±5,6 điểm. Muốn sai số còn khoảng ±2,8 điểm, cần cỡ mẫu bao nhiêu?',
    unit:'người', ans:1200, tol:0, wrong:[[600,'SAI_TINH_TOAN'],[150,'SAI_TINH_TOAN']], errors:['SAI_TINH_TOAN'],
    steps:['Sai số tỉ lệ nghịch với căn bậc hai của n.','Giảm sai số một nửa → n tăng 2² = 4 lần.','300 × 4 = <b>1.200 người</b>.'] },
  { type:'mcq', stem:'Nhóm có mẫu nhỏ mỗi tháng (150 người). Cách đọc xu hướng hợp lý nhất?',
    options:[{k:'a',t:'Đọc từng tháng và phản ứng ngay khi đổi hơn 3 điểm'},{k:'b',t:'Bỏ hẳn khảo sát vì mẫu nhỏ không có giá trị gì'},
             {k:'c',t:'Chỉ báo cáo tháng nào có số đẹp để giữ tinh thần nhóm'},{k:'d',t:'Gộp ba tháng thành trung bình trượt để giảm dao động'}],
    answer:'d', why:{a:'Với 150 người, sai số khoảng ±7 điểm; 3 điểm chỉ là nhiễu.',
      b:'Mẫu nhỏ vẫn có ích khi gộp kỳ hoặc để bắt thay đổi lớn.',
      c:'Chọn số đẹp là làm hỏng mục đích đo.',
      d:'Đúng. Gộp ba tháng tương đương mẫu 450 người, sai số nhỏ hơn đáng kể.'} },
  { type:'mcq', stem:'Nhận biết toàn mẫu 1.000 người đáng tin, nhưng nhóm tuổi 18–24 chỉ có 80 người. Đọc số của nhóm này thế nào?',
    options:[{k:'a',t:'Sai số tính theo 80 người nên rộng hơn nhiều'},{k:'b',t:'Chính xác như toàn mẫu vì cùng một đợt khảo sát'},
             {k:'c',t:'Loại khỏi báo cáo vì nhóm này không quan trọng'},{k:'d',t:'Nhân 80 lên 1.000 để có con số chuẩn hơn cho nhóm tuổi trẻ'}],
    answer:'a', why:{a:'Đúng. Mỗi nhóm con có sai số riêng theo cỡ nhóm; 80 người là khoảng ±10 điểm.',
      b:'Cùng đợt không làm nhóm nhỏ chính xác hơn.',
      c:'Nhóm nhỏ trong mẫu vẫn có thể là nhóm quan trọng; cần mẫu tăng cường nếu muốn đọc.',
      d:'Nhân lên không tạo thêm thông tin; sai số vẫn theo 80 người thật.'} },
  { type:'mcq', stem:'Hai quý liên tiếp giảm 3 điểm, quý thứ ba giảm tiếp 3 điểm, mẫu 250 mỗi quý. Nhận định nào hợp lý?',
    options:[{k:'a',t:'Vẫn là nhiễu vì mỗi mức giảm đều nhỏ hơn sai số của từng quý'},{k:'b',t:'Chắc chắn giảm đúng 9 điểm, cần tăng ngân sách tương ứng'},
             {k:'c',t:'Ba lần giảm cùng chiều, tổng 9 điểm, là tín hiệu đáng xem xét'},{k:'d',t:'Không kết luận được gì nếu không làm lại cả ba quý'}],
    answer:'c', why:{a:'Từng mức nhỏ, nhưng cùng chiều nhiều kỳ và tổng vượt sai số thì khó là ngẫu nhiên.',
      b:'Mức thật vẫn có sai số; "đúng 9 điểm" là quá chắc.',
      c:'Đúng. Xu hướng nhất quán qua nhiều kỳ đáng tin hơn một lần đo.',
      d:'Không cần làm lại; dữ liệu nhiều kỳ đã cho tín hiệu.'} } ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:dl05-09', skill:'measure', read:'7 phút', t:'Đo thương hiệu mỗi quý: theo dõi những gì cho đủ mà không rối?',
  situation:'Một hãng cà phê hoà tan có ngân sách đo lường 200 triệu đồng một năm. Năm nay nhóm đã làm ba khảo sát khác nhau với ba công ty, mỗi lần một bộ câu hỏi, một cách chọn mẫu. Cuối năm, không ai trả lời được câu "thương hiệu mạnh lên hay yếu đi".',
  concept:{ name:'Theo dõi thương hiệu định kỳ (brand tracking)',
    body:'Theo dõi định kỳ chỉ có giá trị khi <b>giữ nguyên</b> ba thứ qua các kỳ: định nghĩa tổng thể và cách chọn mẫu, câu chữ và thứ tự câu hỏi, và rổ đối thủ. Một bộ theo dõi gọn thường gồm: nhận biết không nhắc và có nhắc, cân nhắc, ưa thích, mua gần đây, vài liên tưởng chính; cộng với chỉ báo rẻ hàng tháng như share of search và cảm xúc ròng. Nhịp quý hợp với phần lớn ngành tiêu dùng: đủ dài để thay đổi hiện ra, đủ ngắn để điều chỉnh kế hoạch.' },
  example:'Nhóm dồn 200 triệu vào một bộ theo dõi: bốn đợt mỗi năm, mỗi đợt 600 người qua cùng một panel, cùng chỉ tiêu vùng và tuổi, cùng 12 câu hỏi, rổ năm đối thủ. Chi phí khoảng 45 triệu mỗi đợt, tổng 180 triệu; 20 triệu còn lại cho công cụ tìm kiếm và lắng nghe hàng tháng. Cuối năm có chuỗi bốn điểm so được với nhau và với đối thủ, trả lời được câu hỏi mạnh hay yếu đi.',
  takeaway:'Chuỗi số đo cùng cách qua nhiều kỳ đáng giá hơn nhiều khảo sát lẻ tẻ, dù từng khảo sát lẻ chi tiết hơn.',
  apply:'Liệt kê 6 chỉ số bạn sẽ theo dõi mỗi quý cho một thương hiệu, và 2 chỉ báo rẻ hàng tháng. Nói lý do chọn mỗi cái trong một câu.',
  mistakes:['Đổi câu hỏi hoặc nhà cung cấp mỗi kỳ khiến chuỗi số không so được.','Theo dõi quá nhiều chỉ số, không ai đọc hết.'],
  q:[
  { type:'mcq', stem:'Ba khảo sát khác nhau trong năm mà không trả lời được thương hiệu mạnh lên hay yếu đi. Bạn đoán lý do chính?',
    options:[{k:'a',t:'Mỗi đợt đo một cách nên không so được với nhau'},{k:'b',t:'Ngân sách 200 triệu quá ít để đo thương hiệu một cách nghiêm túc'},
             {k:'c',t:'Các công ty khảo sát đều làm sai'},{k:'d',t:'Thương hiệu không thay đổi gì nên không có gì để nói'}],
    answer:'a', why:{a:'Đúng. Đổi mẫu, câu hỏi và nhà cung cấp làm mất khả năng so sánh.',
      b:'200 triệu đủ cho một bộ theo dõi gọn; vấn đề là cách chi.',
      c:'Mỗi đợt có thể đúng theo cách riêng; vấn đề là chúng khác nhau.',
      d:'Không biết thương hiệu có thay đổi hay không chính là vấn đề.'} },
  { type:'mcq', stem:'Sang năm, bạn được giao lập kế hoạch đo lường với cùng 200 triệu. Bạn chọn gì?',
    options:[{k:'a',t:'Một khảo sát lớn 2.000 người cuối năm cho thật chi tiết'},{k:'b',t:'Mỗi quý thuê một công ty khác để có góc nhìn đa dạng'},
             {k:'c',t:'Bốn đợt quý cùng cách đo, cộng chỉ báo tìm kiếm hàng tháng'},{k:'d',t:'Chỉ theo dõi share of search, bỏ hẳn khảo sát cho tiết kiệm ngân sách'}],
    answer:'c', why:{a:'Một điểm đo không cho biết xu hướng và đến quá muộn để điều chỉnh.',
      b:'Đổi nhà cung cấp mỗi kỳ lặp lại đúng lỗi năm nay.',
      c:'Đúng. Chuỗi đều đặn cộng chỉ báo rẻ cho cả xu hướng lẫn cảnh báo sớm.',
      d:'Tìm kiếm không đo được cân nhắc, ưa thích, liên tưởng; cần cả hai.'} },
  { type:'calc', stem:'Ngân sách năm 240 triệu. Dành 30 triệu cho công cụ theo dõi hàng tháng, phần còn lại chia đều cho bốn đợt khảo sát quý. Mỗi người trả lời tốn 75.000đ. Mỗi đợt được bao nhiêu người?',
    unit:'người', ans:700, tol:0, wrong:[[800,'QUEN_CHI_PHI_CO_DINH'],[2800,'SAI_TINH_TOAN']], errors:['QUEN_CHI_PHI_CO_DINH','SAI_TINH_TOAN'],
    steps:['Tiền cho khảo sát: 240 − 30 = 210 triệu.','Mỗi đợt: 210 ÷ 4 = 52,5 triệu.','Cỡ mẫu: 52.500.000 ÷ 75.000 = <b>700 người</b>.'] },
  { type:'mcq', stem:'Giữa năm, một thành viên muốn sửa câu hỏi cân nhắc cho "hay hơn". Bạn xử lý thế nào?',
    options:[{k:'a',t:'Sửa ngay vì câu hỏi tốt hơn thì dữ liệu tốt hơn'},{k:'b',t:'Giữ câu cũ cho chuỗi; nếu cần, chạy song song cả hai trong một kỳ'},
             {k:'c',t:'Sửa và ghi chú nhỏ trong báo cáo rằng câu hỏi đã được cải tiến'},{k:'d',t:'Bỏ luôn câu cân nhắc để tránh tranh cãi trong nhóm'}],
    answer:'b', why:{a:'Đổi câu chữ làm chuỗi bị gãy; con số mới không so được với cũ.',
      b:'Đúng. Chạy song song một kỳ cho biết độ lệch giữa hai câu, giữ được chuỗi.',
      c:'Ghi chú không giúp so sánh; người đọc vẫn thấy một bước nhảy giả.',
      d:'Cân nhắc là tầng quan trọng của phễu; bỏ đi là mất thông tin.'} },
  { type:'mcq', stem:'Vì sao nhịp quý thường hợp hơn nhịp tháng cho khảo sát thương hiệu ngành tiêu dùng?',
    options:[{k:'a',t:'Vì công ty khảo sát chỉ nhận làm theo quý'},{k:'b',t:'Vì mọi thương hiệu đều thay đổi đúng theo chu kỳ ba tháng'},
             {k:'c',t:'Vì báo cáo quý là quy định bắt buộc của mọi doanh nghiệp'},{k:'d',t:'Thương hiệu đổi chậm; đo tháng tốn tiền mà chủ yếu thấy nhiễu'}],
    answer:'d', why:{a:'Có thể làm theo tháng; vấn đề là chi phí so với giá trị.',
      b:'Không có chu kỳ cố định; quý là mức cân bằng thực tế.',
      c:'Không có quy định như vậy cho khảo sát thương hiệu.',
      d:'Đúng. Với cùng ngân sách, mẫu quý lớn hơn và thay đổi thật dễ thấy hơn.'} },
  { type:'mcq', stem:'Một hãng thời trang theo dõi 40 chỉ số mỗi quý. Vấn đề hay gặp nhất là gì?',
    options:[{k:'a',t:'Chi phí khảo sát tăng gấp nhiều lần so với bộ gọn'},{k:'b',t:'Luôn có vài chỉ số đổi do ngẫu nhiên, gây nhiễu quyết định'},
             {k:'c',t:'Khách trả lời nhanh hơn vì quen câu hỏi'},{k:'d',t:'Không có vấn đề gì, càng nhiều chỉ số thì càng hiểu thương hiệu sâu hơn'}],
    answer:'b', why:{a:'Chi phí tăng một phần, nhưng vấn đề lớn hơn là đọc và quyết định.',
      b:'Đúng. Với 40 chỉ số, vài cái sẽ "đổi đáng kể" chỉ do ngẫu nhiên; nhóm dễ phản ứng sai.',
      c:'Phiếu dài thường làm khách trả lời qua loa, không nhanh hơn một cách tốt.',
      d:'Nhiều chỉ số làm loãng sự chú ý và tăng báo động giả.'} },
  { type:'mcq', stem:'Tại sao cần giữ nguyên rổ đối thủ trong bộ theo dõi?',
    options:[{k:'a',t:'Để thứ hạng và tỉ lệ tương đối so được qua các kỳ'},{k:'b',t:'Vì đối thủ không bao giờ thay đổi trong thị trường'},
             {k:'c',t:'Để thương hiệu của mình luôn đứng trong top đầu bảng'},{k:'d',t:'Vì thêm đối thủ mới vào phiếu khảo sát sẽ làm tăng chi phí in'}],
    answer:'a', why:{a:'Đúng. Thêm bớt tên trong danh sách gợi ý làm thay đổi câu trả lời có nhắc.',
      b:'Đối thủ có thay đổi; khi đó cần thêm có kế hoạch và chạy song song.',
      c:'Mục đích là so công bằng, không phải xếp hạng đẹp.',
      d:'Chi phí in không phải lý do; khảo sát phần lớn đã online.'} } ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:dl05-10', skill:'measure', read:'7 phút', t:'Sếp chỉ có hai phút: báo cáo sức khoẻ thương hiệu một trang trông thế nào?',
  situation:'Bạn phụ trách thương hiệu một hãng sữa chua nội địa. Bộ theo dõi quý có 12 chỉ số, cộng tìm kiếm và lắng nghe mạng xã hội hàng tháng. Báo cáo quý trước dài 38 trang, tổng giám đốc lật hai trang đầu rồi hỏi "vậy mình ổn không?". Quý này bạn được yêu cầu gói lại trong một trang.',
  concept:{ name:'Báo cáo sức khoẻ thương hiệu một trang',
    body:'Một trang tốt trả lời ba câu theo thứ tự: <b>Mình ổn không?</b> (một câu kết luận), <b>Vì sao?</b> (3–5 chỉ số chính, mỗi chỉ số có giá trị, thay đổi so với kỳ trước, so với đối thủ, và đánh dấu thay đổi nào vượt sai số), <b>Làm gì?</b> (1–2 đề xuất có chủ sở hữu). Chỉ số chọn theo phễu: nhận biết, cân nhắc, ưa thích, cộng một chỉ báo sớm như share of search. Phần chi tiết để ở phụ lục cho người muốn đào sâu.' },
  example:'Kết luận: "Thương hiệu ổn về nhận biết, đang tắc ở cân nhắc." Bảng: nhận biết có nhắc 72% (+1, trong sai số), cân nhắc 31% (−5, vượt sai số ±3,5 với mẫu 700), ưa thích 14% (−1), share of search 21% (thị phần 19%). Chủ đề tiêu cực nổi lên: "nhiều đường". Đề xuất: nhóm sản phẩm thử dòng ít đường trong quý tới; nhóm truyền thông đưa thông tin lượng đường lên bao bì mặt trước. Tổng giám đốc đọc trong 90 giây và duyệt.',
  takeaway:'Một trang: một câu kết luận, vài chỉ số có so sánh và sai số, một hai việc cần làm có người chịu trách nhiệm.',
  apply:'Viết câu kết luận mở đầu và chọn bốn chỉ số cho báo cáo một trang về một thương hiệu bạn biết. Mỗi chỉ số ghi rõ so với cái gì.',
  mistakes:['Đưa mọi chỉ số lên trang đầu và để người đọc tự kết luận.','Báo con số mà không có so sánh với kỳ trước, đối thủ hay sai số.'],
  q:[
  { type:'mcq', stem:'Tổng giám đốc lật hai trang rồi hỏi "vậy mình ổn không?". Bạn đoán báo cáo 38 trang thiếu gì?',
    options:[{k:'a',t:'Thiếu biểu đồ đẹp và màu sắc để giữ người đọc lâu hơn'},{k:'b',t:'Thiếu số liệu, cần thêm chỉ số'},
             {k:'c',t:'Thiếu câu kết luận ngay đầu trang'},{k:'d',t:'Thiếu phần phương pháp giải thích cách lấy mẫu chi tiết'}],
    answer:'c', why:{a:'Hình thức không thay được câu trả lời cho câu hỏi chính.',
      b:'Báo cáo đã thừa số liệu; thêm nữa càng khó đọc.',
      c:'Đúng. Người đọc bận cần câu trả lời trước, bằng chứng sau.',
      d:'Phương pháp quan trọng nhưng thuộc phụ lục, không phải thứ sếp cần đầu tiên.'} },
  { type:'mcq', stem:'Bạn chỉ còn chỗ cho bốn chỉ số trên trang. Bạn chọn bộ nào?',
    options:[{k:'a',t:'Lượt thích, lượt chia sẻ, lượt xem video, lượt theo dõi fanpage'},{k:'b',t:'Nhận biết, cân nhắc, ưa thích, share of search'},
             {k:'c',t:'12 chỉ số nén thành chữ nhỏ cho vừa một trang'},{k:'d',t:'Bốn chỉ số có mức tăng lớn nhất quý này để tạo ấn tượng'}],
    answer:'b', why:{a:'Đây là chỉ số hoạt động kênh, không đo sức khoẻ thương hiệu trong đầu khách.',
      b:'Đúng. Phủ các tầng phễu và thêm một chỉ báo sớm.',
      c:'Nén chữ vẫn là 12 chỉ số; mục đích một trang là chọn lọc.',
      d:'Chọn theo độ đẹp che mất chỗ đang tắc.'} },
  { type:'calc', stem:'Cân nhắc giảm từ 36% xuống 31%. Mẫu mỗi kỳ 700 người, sai số ước khoảng ±3,5 điểm. Mức giảm vượt sai số bao nhiêu điểm phần trăm?',
    unit:'điểm %', ans:1.5, tol:0.1, wrong:[[5,'SAI_TINH_TOAN'],[13.9,'NHAM_DIEM_PHAN_TRAM']], errors:['SAI_TINH_TOAN','NHAM_DIEM_PHAN_TRAM'],
    steps:['Mức giảm: 36 − 31 = 5 điểm.','Vượt sai số: 5 − 3,5 = <b>1,5 điểm</b>, đủ để đánh dấu là thay đổi đáng chú ý.'] },
  { type:'mcq', stem:'Đề xuất nào viết đúng cho phần "Làm gì?" của báo cáo một trang?',
    options:[{k:'a',t:'"Cần nâng cao hình ảnh thương hiệu trong tâm trí người tiêu dùng"'},{k:'b',t:'"Tiếp tục theo dõi sát sao các chỉ số trong những quý tiếp theo"'},
             {k:'c',t:'"Tăng cường truyền thông đa kênh"'},{k:'d',t:'"Nhóm sản phẩm thử dòng ít đường ở 50 cửa hàng trong quý 4"'}],
    answer:'d', why:{a:'Chung chung, không có việc cụ thể và người chịu trách nhiệm.',
      b:'Theo dõi là việc mặc định, không phải đề xuất hành động.',
      c:'Không nói kênh nào, làm gì, ai làm.',
      d:'Đúng. Có việc cụ thể, phạm vi, thời hạn và chủ sở hữu.'} },
  { type:'mcq', stem:'Nhận biết tăng 1 điểm, nằm trong sai số. Trình bày trên trang thế nào cho đúng?',
    options:[{k:'a',t:'Ghi "+1, trong sai số" để người đọc không hiểu nhầm'},{k:'b',t:'Ghi "tăng" bằng màu xanh cho tinh thần tích cực trong nhóm'},
             {k:'c',t:'Bỏ chỉ số nhận biết khỏi trang vì không đổi'},{k:'d',t:'Ghi "giảm" để an toàn, phòng khi con số thật thấp hơn'}],
    answer:'a', why:{a:'Đúng. Đánh dấu sai số giúp người đọc biết thay đổi nào đáng phản ứng.',
      b:'Tô xanh khiến sếp nghĩ có tiến bộ thật.',
      c:'Nhận biết ổn định cũng là thông tin; bỏ đi làm mất tầng đầu phễu.',
      d:'Ghi ngược hướng là sai sự thật.'} },
  { type:'mcq', stem:'Quý này mọi chỉ số đều ổn định, không có gì vượt sai số. Câu kết luận đầu trang nên là gì?',
    options:[{k:'a',t:'Bỏ trống câu kết luận vì không có tin gì mới để báo'},{k:'b',t:'Chọn một chỉ số tăng nhẹ nhất và nhấn mạnh nó như một thành tích'},
             {k:'c',t:'"Ổn định; chưa cần đổi kế hoạch, theo dõi cân nhắc"'},{k:'d',t:'"Thương hiệu đang chững lại, cần hành động ngay"'}],
    answer:'c', why:{a:'"Ổn định" là một kết luận có giá trị; người đọc cần biết.',
      b:'Thổi phồng một thay đổi trong sai số làm mất niềm tin vào báo cáo.',
      c:'Đúng. Kết luận rõ, trung thực, và chỉ ra điểm cần để ý.',
      d:'Ổn định không phải chững lại; báo động giả dẫn tới chi tiêu sai.'} },
  { type:'mcq', stem:'Giám đốc tài chính hỏi: "Nhận biết 72% thì có nghĩa gì với doanh số?" Câu trả lời tốt nhất?',
    options:[{k:'a',t:'"Nhận biết càng cao thì doanh số càng cao theo tỉ lệ một – một"'},{k:'b',t:'"Không liên quan, thương hiệu và doanh số là hai chuyện riêng"'},
             {k:'c',t:'"Chỉ phòng marketing mới cần hiểu các chỉ số này"'},{k:'d',t:'"Nhận biết đã đủ rộng; tầng cân nhắc đang kìm doanh số"'}],
    answer:'d', why:{a:'Không có quan hệ một – một; phải đọc qua các tầng phễu.',
      b:'Các tầng phễu thương hiệu dẫn tới mua; nói không liên quan là sai.',
      c:'Báo cáo tồn tại để người ngoài marketing ra quyết định.',
      d:'Đúng. Nối chỉ số với doanh số qua phễu và chỉ ra chỗ tắc.'} } ] }

]});
